import styles from "./index.module.scss";

const StatusIcon = () => {
  return (
    <svg
      width="12"
      height="18"
      viewBox="0 0 12 18"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path d="M6 9C6 10.6569 4.65685 12 3 12C1.34315 12 0 10.6569 0 9C0 7.34315 1.34315 6 3 6C4.65685 6 6 7.34315 6 9Z" />
    </svg>
  );
};

const TrendingIcon = () => {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="16"
      height="16"
      fill="#ff9500"
      viewBox="0 0 256 256"
    >
      <path
        d="M208,144a80,80,0,0,1-160,0c0-30.57,14.42-58.26,31-80l33,32,26.27-72C159.86,41.92,208,88.15,208,144Z"
        opacity="0.2"
      ></path>
      <path d="M183.89,153.34a57.6,57.6,0,0,1-46.56,46.55A8.75,8.75,0,0,1,136,200a8,8,0,0,1-1.32-15.89c16.57-2.79,30.63-16.85,33.44-33.45a8,8,0,0,1,15.78,2.68ZM216,144a88,88,0,0,1-176,0c0-27.92,11-56.47,32.66-84.85a8,8,0,0,1,11.93-.89l24.12,23.41,22-60.41a8,8,0,0,1,12.63-3.41C165.21,36,216,84.55,216,144Zm-16,0c0-46.09-35.79-85.92-58.21-106.33L119.52,98.74a8,8,0,0,1-13.09,3L80.06,76.16C64.09,99.21,56,122,56,144a72,72,0,0,0,144,0Z"></path>
    </svg>
  );
};

export default function WorkFlowStatus({ status }) {
  const colors = {
    inProgress: "#007AFF",
    inTesting: "#FF9500",
    finished: "#34C759",
    comingSoon: "#8E8E93",
  };

  const inPrgress = {
    borderColor: colors.inProgress,
    color: colors.inProgress,
    fill: colors.inProgress,
  };
  const inTesting = {
    borderColor: colors.inTesting,
    color: colors.inTesting,
    fill: colors.inTesting,
  };
  const finished = {
    borderColor: colors.finished,
    color: colors.finished,
    fill: colors.finished,
  };
  const comingSoon = {
    borderColor: colors.comingSoon,
    color: colors.comingSoon,
    fill: colors.comingSoon,
  };

  return (
    <div className={`${styles.flowBadge}`}>
      {(() => {
        switch (status) {
          case "In Progress":
            return (
              <span style={inPrgress}>
                <StatusIcon /> {status}
              </span>
            );
          case "Trending":
            return (
              <span style={inTesting}>
                <TrendingIcon /> {status}
              </span>
            );
          case "Finished":
            return (
              <span style={finished}>
                <StatusIcon /> {status}
              </span>
            );
          case "Coming Soon":
            return (
              <span style={comingSoon}>
                <StatusIcon /> {status}
              </span>
            );
          default:
            return null;
        }
      })()}
    </div>
  );
}
